:root {
  --color-bg-primary: #0a0e27;
  --color-bg-secondary: #0f1535;
  --color-bg-tertiary: #1a1f3a;
  --color-text-primary: #e8eef7;
  --color-text-secondary: #a8b2cc;
  --color-text-muted: #7a839f;
  --color-accent: #d4af37;
  --color-accent-dark: #b8960f;
  --color-link: #64b5f6;
  --color-link-hover: #90caf9;
  --color-border: #2d3547;
  --color-focus: #64b5f6;
  --color-success: #66bb6a;
  --color-error: #ef5350;

  --spacing-xs: 0.25rem;
  --spacing-sm: 0.5rem;
  --spacing-md: 1rem;
  --spacing-lg: 1.5rem;
  --spacing-xl: 2rem;
  --spacing-2xl: 3rem;

  --radius-sm: 0.25rem;
  --radius-md: 0.5rem;
  --radius-lg: 1rem;

  --font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  --font-mono: 'Monaco', 'Menlo', monospace;

  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.3);
  --shadow-md: 0 4px 6px rgba(0, 0, 0, 0.4);
  --shadow-lg: 0 10px 15px rgba(0, 0, 0, 0.5);

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
}

/* === Global Styles === */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-family);
  background-color: var(--color-bg-primary);
  color: var(--color-text-primary);
  line-height: 1.6;
  font-size: 16px;
}

/* === Screen Reader Only === */
.sr-only:not(:focus):not(:active) {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}

/* === Typography === */
h1, h2, h3, h4, h5, h6 {
  font-weight: 600;
  line-height: 1.2;
  color: var(--color-text-primary);
}

h1 {
  font-size: 2.5rem;
}

h2 {
  font-size: 2rem;
  margin-bottom: var(--spacing-xl);
}

h3 {
  font-size: 1.25rem;
}

p {
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-md);
}

a {
  color: var(--color-link);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover,
a:focus {
  color: var(--color-link-hover);
  outline: none;
}

a:focus-visible {
  outline: 2px solid var(--color-focus);
  outline-offset: 2px;
}

/* === Container === */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-xl);
}

/* === Header === */
header {
  background-color: var(--color-bg-secondary);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-top {
  background-color: var(--color-bg-secondary);
}

.header-content {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-lg) 0;
  max-width: 1200px;
  margin: 0 auto;
  padding-left: var(--spacing-xl);
  padding-right: var(--spacing-xl);
}

.logo {
  display: flex;
  align-items: center;
  gap: var(--spacing-md);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-accent);
  transition: color var(--transition-fast);
}

.logo:hover,
.logo:focus {
  color: var(--color-accent-dark);
}

.logo svg {
  width: 32px;
  height: 32px;
  fill: currentColor;
}

/* === Navigation === */
.nav-main {
  flex: 1;
  display: flex;
  justify-content: center;
}

.nav-toggle {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: var(--spacing-md);
  margin-left: var(--spacing-lg);
}

.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background-color: var(--color-text-primary);
  margin: 6px 0;
  transition: var(--transition-fast);
}

.nav-list {
  display: flex;
  gap: var(--spacing-2xl);
  list-style: none;
}

.nav-list a {
  color: var(--color-text-primary);
  padding: var(--spacing-md) 0;
  position: relative;
  font-weight: 500;
}

.nav-list a::after {
  content: '';
  position: absolute;
  width: 0;
  height: 2px;
  bottom: -2px;
  left: 0;
  background-color: var(--color-accent);
  transition: width var(--transition-fast);
}

.nav-list a:hover::after,
.nav-list a:focus::after {
  width: 100%;
}

/* === Header Actions === */
.header-actions {
  display: flex;
  gap: var(--spacing-lg);
}

.icon-btn {
  background: none;
  border: none;
  color: var(--color-text-primary);
  cursor: pointer;
  padding: var(--spacing-md);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: color var(--transition-fast);
  border-radius: var(--radius-md);
}

.icon-btn:hover {
  color: var(--color-accent);
}

.icon-btn:focus-visible {
  outline: 2px solid var(--color-focus);
  outline-offset: 2px;
}

.icon-btn svg {
  width: 20px;
  height: 20px;
  fill: currentColor;
}

/* === Main Content === */
main {
  min-height: calc(100vh - 200px);
}

/* === Hero Section === */
.hero {
  background: linear-gradient(135deg, var(--color-bg-tertiary) 0%, var(--color-bg-primary) 100%);
  padding: 6rem var(--spacing-xl);
  text-align: center;
  border-bottom: 1px solid var(--color-border);
}

.hero-content h2 {
