}

.product-info {
  padding: var(--spacing-lg);
}

.product-info h3 {
  margin-bottom: var(--spacing-sm);
}

.product-price {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-accent);
  margin-bottom: var(--spacing-sm);
}

.price-original {
  text-decoration: line-through;
  color: var(--color-text-muted);
