  transition: color var(--transition-fast);
}

.read-more:hover,
.read-more:focus {
  color: var(--color-accent-dark);
}

/* === Newsletter === */
.newsletter {
  text-align: center;
}

.newsletter h2 {
  color: var(--color-accent);
}

.newsletter-form {
  display: flex;
  gap: var(--spacing-md);
  justify-content: center;
  flex-wrap: wrap;
