}

.footer-section a {
  color: var(--color-text-secondary);
}

.footer-section a:hover {
  color: var(--color-accent);
}

.footer-bottom {
  background-color: var(--color-bg-primary);
  border-top: 1px solid var(--color-border);
  padding: var(--spacing-lg) 0;
}

.footer-bottom .container {
  display: flex;
