      this.newsletterNotice.textContent = `✓ Thank you! Check your email for a special welcome offer.`;
      this.newsletterNotice.style.color = 'var(--color-success)';
      this.emailInput.value = '';

      this.newsletterForm.style.opacity = '1';
      this.newsletterForm.style.pointerEvents = 'auto';

      // Clear message after 5 seconds
      setTimeout(() => {
        this.newsletterNotice.textContent = '';
      }, 5000);
    }, 800);
  }

  /**
