   */
  setupCountdowns() {
    const countdowns = document.querySelectorAll('.countdown');

    countdowns.forEach(el => {
      this.updateCountdown(el);
    });
  }

  /**
   * Update individual countdown
   */
  updateCountdown(element) {
    // Parse the countdown text to extract values
    const text = element.textContent;

    // Simple countdown updates - in production would use actual time calculation
    // This just demonstrates the pattern
    if (text.includes('d')) {
      // Countdown with days
      const updateDaily = () => {
        // Simulated countdown - doesn't actually decrement
        // In production, calculate from target time
      };
      updateDaily();
    }
  }
}

/**
 * Product card functionality
 */
class ProductCard {
  constructor(cardElement) {
    this.card = cardElement;
    this.button = cardElement.querySelector('.btn-small');
    this.init();
  }

  init() {
    if (!this.button) return;

    this.button.addEventListener('click', (e) => {
      e.preventDefault();
      this.addToCart();
    });
  }

  addToCart() {
    const productName = this.card.querySelector('h3 a').textContent;
    const button = this.button;
    const originalText = button.textContent;

    // Visual feedback
    button.textContent = '✓ Added';
    button.style.backgroundColor = 'var(--color-success)';

    // Reset after 2 seconds
    setTimeout(() => {
      button.textContent = originalText;
      button.style.backgroundColor = '';
    }, 2000);

    // Live region announcement for screen readers
    this.announceToScreenReader(`${productName} added to cart`);
  }

  /**
   * Announce action to screen readers
   */
  announceToScreenReader(message) {
    const announcement = document.createElement('div');
    announcement.setAttribute('role', 'status');
    announcement.setAttribute('aria-live', 'polite');
    announcement.className = 'sr-only';
    announcement.textContent = message;
    document.body.appendChild(announcement);

    setTimeout(() => {
      announcement.remove();
    }, 1000);
  }
}

/**
 * Initialize product cards
 */
function initializeProductCards() {
  const cards = document.querySelectorAll('.product-card');
  cards.forEach(card => {
    new ProductCard(card);
  });
}

/**
 * Setup search functionality
 */
function setupSearch() {
  const searchBtn = document.querySelector('.search-btn');
  if (!searchBtn) return;

  searchBtn.addEventListener('click', () => {
    // Placeholder for search functionality
    console.log('Search clicked');
  });
}

/**
 * Setup cart functionality
 */
function setupCart() {
  const cartBtn = document.querySelector('.cart-btn');
  if (!cartBtn) return;

  cartBtn.addEventListener('click', () => {
    // Placeholder for cart view
    console.log('Cart clicked');
  });
}

/**
 * Enhance links with proper keyboard handling
 */
function setupLinks() {
  const allLinks = document.querySelectorAll('a[href="#"]');

  allLinks.forEach(link => {
    link.addEventListener('click', (e) => {
      // Prevent navigation for demo links
      if (link.getAttribute('href') === '#') {
        e.preventDefault();
      }
    });
  });
}

/**
 * Initialize page on DOM ready
 */
document.addEventListener('DOMContentLoaded', () => {
  new ShoppingPage();
  initializeProductCards();
  setupSearch();
  setupCart();
  setupLinks();
});

/**
 * Handle skip link functionality
 */
const skipLink = document.querySelector('.sr-only');
if (skipLink && skipLink.getAttribute('href') === '#maincontent') {
  skipLink.addEventListener('click', (e) => {
    const mainContent = document.querySelector('#maincontent');
    if (mainContent) {
      mainContent.focus();
      mainContent.scrollIntoView({ behavior: 'smooth' });
    }
  });
}
