/* === CSS Variables (Design Tokens) === */
:root {
  --color-bg-primary: #0a0e27;
  --color-bg-secondary: #0f1535;
  --color-bg-tertiary: #1a1f3a;
  --color-text-primary: #e8eef7;
  --color-text-secondary: #a8b2cc;
  --color-text-muted: #7a839f;
  --color-accent: #d4af37;
  --color-accent-dark: #b8960f;
  --color-link: #64b5f6;
  --color-link-hover: #90caf9;
  --color-border: #2d3547;
  --color-focus: #64b5f6;
  --color-success: #66bb6a;
  --color-error: #ef5350;

  --spacing-xs: 0.25rem;
  --spacing-sm: 0.5rem;
  --spacing-md: 1rem;
  --spacing-lg: 1.5rem;
  --spacing-xl: 2rem;
  --spacing-2xl: 3rem;

  --radius-sm: 0.25rem;
  --radius-md: 0.5rem;
  --radius-lg: 1rem;

  --font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  --font-mono: 'Monaco', 'Menlo', monospace;

  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.3);
  --shadow-md: 0 4px 6px rgba(0, 0, 0, 0.4);
  --shadow-lg: 0 10px 15px rgba(0, 0, 0, 0.5);

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
}

/* === Global Styles === */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-family);
  background-color: var(--color-bg-primary);
  color: var(--color-text-primary);
  line-height: 1.6;
  font-size: 16px;
}

/* === Screen Reader Only === */
.sr-only:not(:focus):not(:active) {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}

/* === Typography === */
h1, h2, h3, h4, h5, h6 {
  font-weight: 600;
  line-height: 1.2;
  color: var(--color-text-primary);
}

h1 {
  font-size: 2.5rem;
}

h2 {
  font-size: 2rem;
  margin-bottom: var(--spacing-xl);
}

h3 {
  font-size: 1.25rem;
}

p {
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-md);
}

a {
  color: var(--color-link);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover,
a:focus {
  color: var(--color-link-hover);
  outline: none;
}

a:focus-visible {
  outline: 2px solid var(--color-focus);
  outline-offset: 2px;
}

/* === Container === */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-xl);
}

/* === Header === */
header {
  background-color: var(--color-bg-secondary);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-top {
  background-color: var(--color-bg-secondary);
}

.header-content {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-lg) 0;
  max-width: 1200px;
  margin: 0 auto;
  padding-left: var(--spacing-xl);
  padding-right: var(--spacing-xl);
}

.logo {
  display: flex;
  align-items: center;
  gap: var(--spacing-md);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-accent);
  transition: color var(--transition-fast);
}

.logo:hover,
.logo:focus {
  color: var(--color-accent-dark);
}

.logo svg {
  width: 32px;
  height: 32px;
  fill: currentColor;
}

/* === Navigation === */
.nav-main {
  flex: 1;
  display: flex;
  justify-content: center;
}

.nav-toggle {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: var(--spacing-md);
  margin-left: var(--spacing-lg);
}

.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background-color: var(--color-text-primary);
  margin: 6px 0;
  transition: var(--transition-fast);
}

.nav-list {
  display: flex;
  gap: var(--spacing-2xl);
  list-style: none;
}

.nav-list a {
  color: var(--color-text-primary);
  padding: var(--spacing-md) 0;
  position: relative;
  font-weight: 500;
}

.nav-list a::after {
  content: '';
  position: absolute;
  width: 0;
  height: 2px;
  bottom: -2px;
  left: 0;
  background-color: var(--color-accent);
  transition: width var(--transition-fast);
}

.nav-list a:hover::after,
.nav-list a:focus::after {
  width: 100%;
}

/* === Header Actions === */
.header-actions {
  display: flex;
  gap: var(--spacing-lg);
}

.icon-btn {
  background: none;
  border: none;
  color: var(--color-text-primary);
  cursor: pointer;
  padding: var(--spacing-md);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: color var(--transition-fast);
  border-radius: var(--radius-md);
}

.icon-btn:hover {
  color: var(--color-accent);
}

.icon-btn:focus-visible {
  outline: 2px solid var(--color-focus);
  outline-offset: 2px;
}

.icon-btn svg {
  width: 20px;
  height: 20px;
  fill: currentColor;
}

/* === Main Content === */
main {
  min-height: calc(100vh - 200px);
}

/* === Hero Section === */
.hero {
  background: linear-gradient(135deg, var(--color-bg-tertiary) 0%, var(--color-bg-primary) 100%);
  padding: 6rem var(--spacing-xl);
  text-align: center;
  border-bottom: 1px solid var(--color-border);
}

.hero-content h2 {
  font-size: 3rem;
  margin-bottom: var(--spacing-lg);
  color: var(--color-accent);
}

.hero-content p {
  font-size: 1.25rem;
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-xl);
}

/* === Sections === */
.section {
  padding: var(--spacing-2xl) 0;
}

.section-alt {
  background-color: var(--color-bg-secondary);
}

/* === Buttons === */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: var(--spacing-md) var(--spacing-lg);
  border: 2px solid transparent;
  border-radius: var(--radius-md);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition-base);
  text-decoration: none;
}

.btn:focus-visible {
  outline: 2px solid var(--color-focus);
  outline-offset: 2px;
}

.btn-primary {
  background-color: var(--color-accent);
  color: var(--color-bg-primary);
  border-color: var(--color-accent);
}

.btn-primary:hover {
  background-color: var(--color-accent-dark);
  border-color: var(--color-accent-dark);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-secondary {
  background-color: transparent;
  color: var(--color-text-primary);
  border-color: var(--color-border);
}

.btn-secondary:hover {
  background-color: var(--color-bg-tertiary);
  border-color: var(--color-accent);
  color: var(--color-accent);
}

.btn-small {
  padding: var(--spacing-sm) var(--spacing-lg);
  font-size: 0.875rem;
}

/* === Product Grid === */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--spacing-xl);
}

.product-card {
  background-color: var(--color-bg-secondary);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition-base);
}

.product-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

.product-image {
  position: relative;
  overflow: hidden;
  aspect-ratio: 3 / 4;
  background-color: var(--color-bg-tertiary);
}

.product-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-base);
}

.product-card:hover .product-image img {
  transform: scale(1.05);
}

.badge {
  position: absolute;
  top: var(--spacing-md);
  right: var(--spacing-md);
  background-color: var(--color-accent);
  color: var(--color-bg-primary);
  padding: var(--spacing-sm) var(--spacing-md);
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.badge-sale {
  background-color: var(--color-error);
}

.product-info {
  padding: var(--spacing-lg);
}

.product-info h3 {
  margin-bottom: var(--spacing-sm);
}

.product-price {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-accent);
  margin-bottom: var(--spacing-sm);
}

.price-original {
  text-decoration: line-through;
  color: var(--color-text-muted);
  margin-right: var(--spacing-md);
  font-size: 0.875rem;
}

.product-desc {
  font-size: 0.875rem;
  color: var(--color-text-muted);
  margin-bottom: var(--spacing-lg);
}

/* === Deals Grid === */
.deals-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--spacing-xl);
}

.deal-card {
  background: linear-gradient(135deg, var(--color-bg-tertiary) 0%, var(--color-bg-secondary) 100%);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--spacing-xl);
  position: relative;
  overflow: hidden;
  transition: all var(--transition-base);
}

.deal-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(90deg, var(--color-accent), var(--color-link));
}

.deal-card:hover {
  border-color: var(--color-accent);
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.deal-badge {
  display: inline-block;
  background-color: var(--color-accent);
  color: var(--color-bg-primary);
  padding: var(--spacing-xs) var(--spacing-md);
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  margin-bottom: var(--spacing-lg);
}

.deal-card h3 {
  margin-bottom: var(--spacing-md);
  color: var(--color-accent);
}

.deal-description {
  font-size: 1rem;
  margin-bottom: var(--spacing-md);
}

.deal-timing {
  color: var(--color-text-muted);
  font-size: 0.875rem;
  margin-bottom: var(--spacing-lg);
}

.countdown {
  color: var(--color-accent);
  font-weight: 600;
}

/* === Editorial Grid === */
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: var(--spacing-xl);
}

.editorial-card {
  background-color: var(--color-bg-secondary);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition-base);
}

.editorial-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-md);
}

.editorial-image {
  overflow: hidden;
  aspect-ratio: 16 / 9;
  background-color: var(--color-bg-tertiary);
}

.editorial-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-base);
}

.editorial-card:hover .editorial-image img {
  transform: scale(1.05);
}

.editorial-content {
  padding: var(--spacing-xl);
}

.editorial-category {
  display: inline-block;
  color: var(--color-accent);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  margin-bottom: var(--spacing-md);
}

.editorial-card h3 {
  margin-bottom: var(--spacing-md);
}

.editorial-card p {
  margin-bottom: var(--spacing-lg);
  font-size: 0.9rem;
}

.read-more {
  color: var(--color-accent);
  font-weight: 600;
  transition: color var(--transition-fast);
}

.read-more:hover,
.read-more:focus {
  color: var(--color-accent-dark);
}

/* === Newsletter === */
.newsletter {
  text-align: center;
}

.newsletter h2 {
  color: var(--color-accent);
}

.newsletter-form {
  display: flex;
  gap: var(--spacing-md);
  justify-content: center;
  flex-wrap: wrap;
  margin: var(--spacing-xl) 0;
}

.form-group {
  position: relative;
  flex: 1;
  min-width: 250px;
  max-width: 400px;
}

.form-group input {
  width: 100%;
  padding: var(--spacing-md) var(--spacing-lg);
  background-color: var(--color-bg-tertiary);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-md);
  color: var(--color-text-primary);
  font-size: 1rem;
  transition: all var(--transition-fast);
}

.form-group input::placeholder {
  color: var(--color-text-muted);
}

.form-group input:focus-visible {
  outline: none;
  border-color: var(--color-focus);
  background-color: var(--color-bg-secondary);
  box-shadow: 0 0 0 3px rgba(100, 181, 246, 0.1);
}

.form-group input:invalid:not(:placeholder-shown) {
  border-color: var(--color-error);
}

.error-message {
  display: none;
  position: absolute;
  bottom: -1.5rem;
  left: 0;
  color: var(--color-error);
  font-size: 0.875rem;
  margin-top: var(--spacing-sm);
}

.error-message.show {
  display: block;
}

.newsletter-notice {
  margin-top: var(--spacing-lg);
  font-size: 0.9rem;
  color: var(--color-success);
  min-height: 1.5rem;
}

/* === Footer === */
footer {
  background-color: var(--color-bg-secondary);
  border-top: 1px solid var(--color-border);
  margin-top: var(--spacing-2xl);
}

.footer-content {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--spacing-xl);
  padding: var(--spacing-2xl) var(--spacing-xl);
}

.footer-section h3 {
  margin-bottom: var(--spacing-lg);
  color: var(--color-accent);
}

.footer-section ul {
  list-style: none;
}

.footer-section ul li {
  margin-bottom: var(--spacing-md);
}

.footer-section a {
  color: var(--color-text-secondary);
}

.footer-section a:hover {
  color: var(--color-accent);
}

.footer-bottom {
  background-color: var(--color-bg-primary);
  border-top: 1px solid var(--color-border);
  padding: var(--spacing-lg) 0;
}

.footer-bottom .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--spacing-lg);
}

.footer-bottom p {
  margin: 0;
}

.footer-links {
  display: flex;
  gap: var(--spacing-xl);
  list-style: none;
}

.footer-links a {
  color: var(--color-text-secondary);
}

.footer-links a:hover {
  color: var(--color-accent);
}

/* === Responsive Design === */
@media (max-width: 768px) {
  .nav-toggle {
    display: block;
  }

  .nav-list {
    display: none;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    flex-direction: column;
    gap: 0;
    background-color: var(--color-bg-secondary);
    border-bottom: 1px solid var(--color-border);
    padding: var(--spacing-lg) 0;
    z-index: 99;
  }

  .nav-list.active {
    display: flex;
  }

  .nav-list a {
    padding: var(--spacing-md) var(--spacing-xl);
  }

  .product-grid {
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  }

  .hero-content h2 {
    font-size: 2rem;
  }

  h1 {
    font-size: 2rem;
  }

  h2 {
    font-size: 1.5rem;
  }

  .newsletter-form {
    flex-direction: column;
  }

  .form-group {
    min-width: 100%;
    max-width: 100%;
  }

  .footer-bottom .container {
    flex-direction: column;
    align-items: flex-start;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 var(--spacing-lg);
  }

  .header-content {
    padding-left: var(--spacing-lg);
    padding-right: var(--spacing-lg);
  }

  .product-grid {
    grid-template-columns: 1fr;
  }

  .deals-grid {
    grid-template-columns: 1fr;
  }

  .editorial-grid {
    grid-template-columns: 1fr;
  }

  .hero {
    padding: 3rem var(--spacing-lg);
  }

  .hero-content h2 {
    font-size: 1.5rem;
  }

  .nav-list a {
    padding: var(--spacing-md) var(--spacing-lg);
  }

  .section {
    padding: var(--spacing-xl) 0;
  }
}

/* === Forced Colors Support === */
@media (forced-colors: active) {
  .btn,
  .product-card,
  .deal-card,
  .editorial-card {
    border-width: 2px;
    border-color: CanvasText;
  }

  .btn-primary {
    background-color: HighlightText;
    color: Highlight;
    border-color: HighlightText;
  }

  .btn-primary:hover {
    background-color: Highlight;
    color: HighlightText;
  }

  .btn-secondary {
    border-color: CanvasText;
    color: CanvasText;
  }

  .badge,
  .deal-badge {
    background-color: Highlight;
    color: HighlightText;
  }

  .logo {
    color: LinkText;
  }

  a {
    color: LinkText;
    text-decoration: underline;
  }

  .nav-list a::after {
    background-color: LinkText;
  }

  .btn:focus-visible,
  .icon-btn:focus-visible,
