/**
 * Shopping Home Page - Vanilla JavaScript
 * Handles navigation, forms, and interactive features
 */

class ShoppingPage {
  constructor() {
    this.navToggle = document.querySelector('.nav-toggle');
    this.navList = document.querySelector('.nav-list');
    this.navLinks = document.querySelectorAll('.nav-list a');
    this.newsletterForm = document.querySelector('.newsletter-form');
    this.emailInput = document.querySelector('#email-input');
    this.errorMessage = document.querySelector('#email-error');
    this.newsletterNotice = document.querySelector('.newsletter-notice');

    this.init();
  }

  init() {
    this.setupNavigation();
    this.setupForm();
    this.setupCountdowns();
  }

  /**
   * Setup mobile navigation toggle
   */
  setupNavigation() {
    if (!this.navToggle) return;

    this.navToggle.addEventListener('click', () => {
      const isExpanded = this.navToggle.getAttribute('aria-expanded') === 'true';
      this.navToggle.setAttribute('aria-expanded', !isExpanded);
      this.navList.classList.toggle('active');

      if (!isExpanded) {
        this.navToggle.innerHTML = '<span></span><span></span><span></span>';
      }
    });

    // Close menu when a link is clicked
    this.navLinks.forEach(link => {
      link.addEventListener('click', () => {
        this.navToggle.setAttribute('aria-expanded', 'false');
        this.navList.classList.remove('active');
      });
    });

    // Close menu on Escape
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && this.navList.classList.contains('active')) {
        this.navToggle.setAttribute('aria-expanded', 'false');
        this.navList.classList.remove('active');
        this.navToggle.focus();
      }
    });
  }

  /**
   * Setup newsletter form with validation
   */
  setupForm() {
    if (!this.newsletterForm) return;

    this.newsletterForm.addEventListener('submit', (e) => {
      e.preventDefault();

      if (this.validateEmail()) {
        this.submitNewsletter();
      }
    });

    this.emailInput.addEventListener('blur', () => {
      this.validateEmail();
    });

    this.emailInput.addEventListener('input', () => {
      if (this.errorMessage.classList.contains('show')) {
        this.errorMessage.classList.remove('show');
      }
    });
  }

  /**
   * Validate email input
   */
  validateEmail() {
    const email = this.emailInput.value.trim();
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    if (!email) {
      this.showError('Please enter your email address');
      return false;
    }

    if (!emailRegex.test(email)) {
      this.showError('Please enter a valid email address');
      return false;
    }

    this.clearError();
    return true;
  }

  /**
   * Show validation error
   */
  showError(message) {
    this.errorMessage.textContent = message;
    this.errorMessage.classList.add('show');
    this.emailInput.setAttribute('aria-invalid', 'true');
  }

  /**
   * Clear validation error
   */
  clearError() {
    this.errorMessage.textContent = '';
    this.errorMessage.classList.remove('show');
    this.emailInput.setAttribute('aria-invalid', 'false');
  }

  /**
   * Submit newsletter subscription
   */
  submitNewsletter() {
    const email = this.emailInput.value.trim();

    // Simulate API call
    this.newsletterForm.style.opacity = '0.5';
    this.newsletterForm.style.pointerEvents = 'none';

    setTimeout(() => {
      this.newsletterNotice.textContent = `✓ Thank you! Check your email for a special welcome offer.`;
      this.newsletterNotice.style.color = 'var(--color-success)';
      this.emailInput.value = '';

      this.newsletterForm.style.opacity = '1';
      this.newsletterForm.style.pointerEvents = 'auto';

      // Clear message after 5 seconds
      setTimeout(() => {
        this.newsletterNotice.textContent = '';
      }, 5000);
    }, 800);
  }

  /**
   * Update countdown timers
   */
  setupCountdowns() {
    const countdowns = document.querySelectorAll('.countdown');

    countdowns.forEach(el => {
      this.updateCountdown(el);
    });
  }

  /**
   * Update individual countdown
   */
  updateCountdown(element) {
    // Parse the countdown text to extract values
    const text = element.textContent;

    // Simple countdown updates - in production would use actual time calculation
    // This just demonstrates the pattern
    if (text.includes('d')) {
      // Countdown with days
      const updateDaily = () => {
        // Simulated countdown - doesn't actually decrement
        // In production, calculate from target time
      };
      updateDaily();
    }
  }
}

/**
 * Product card functionality
 */
class ProductCard {
  constructor(cardElement) {
    this.card = cardElement;
    this.button = cardElement.querySelector('.btn-small');
    this.init();
  }

  init() {
    if (!this.button) return;

    this.button.addEventListener('click', (e) => {
      e.preventDefault();
      this.addToCart();
    });
  }

  addToCart() {
    const productName = this.card.querySelector('h3 a').textContent;
    const button = this.button;
    const originalText = button.textContent;

    // Visual feedback
    button.textContent = '✓ Added';
    button.style.backgroundColor = 'var(--color-success)';

    // Reset after 2 seconds
    setTimeout(() => {
      button.textContent = originalText;
      button.style.backgroundColor = '';
    }, 2000);

    // Live region announcement for screen readers
    this.announceToScreenReader(`${productName} added to cart`);
  }

  /**
   * Announce action to screen readers
   */
  announceToScreenReader(message) {
    const announcement = document.createElement('div');
    announcement.setAttribute('role', 'status');
    announcement.setAttribute('aria-live', 'polite');
    announcement.className = 'sr-only';
    announcement.textContent = message;
    document.body.appendChild(announcement);

    setTimeout(() => {
      announcement.remove();
    }, 1000);
  }
}

/**
 * Initialize product cards
 */
function initializeProductCards() {
  const cards = document.querySelectorAll('.product-card');
  cards.forEach(card => {
    new ProductCard(card);
  });
}

/**
 * Setup search functionality
 */
function setupSearch() {
  const searchBtn = document.querySelector('.search-btn');
  if (!searchBtn) return;

  searchBtn.addEventListener('click', () => {
    // Placeholder for search functionality
    console.log('Search clicked');
  });
}

/**
 * Setup cart functionality
 */
function setupCart() {
  const cartBtn = document.querySelector('.cart-btn');
  if (!cartBtn) return;

  cartBtn.addEventListener('click', () => {
    // Placeholder for cart view
    console.log('Cart clicked');
  });
}

/**
 * Enhance links with proper keyboard handling
 */
function setupLinks() {
  const allLinks = document.querySelectorAll('a[href="#"]');

  allLinks.forEach(link => {
    link.addEventListener('click', (e) => {
      // Prevent navigation for demo links
      if (link.getAttribute('href') === '#') {
        e.preventDefault();
      }
    });
  });
}

/**
 * Initialize page on DOM ready
 */
document.addEventListener('DOMContentLoaded', () => {
  new ShoppingPage();
  initializeProductCards();
  setupSearch();
  setupCart();
  setupLinks();
});

/**
 * Handle skip link functionality
 */
const skipLink = document.querySelector('.sr-only');
if (skipLink && skipLink.getAttribute('href') === '#maincontent') {
  skipLink.addEventListener('click', (e) => {
    const mainContent = document.querySelector('#maincontent');
    if (mainContent) {
      mainContent.focus();
      mainContent.scrollIntoView({ behavior: 'smooth' });
    }
  });
}

