2.  * Shopping Home Page - Vanilla JavaScript
3.  * Handles navigation, forms, and interactive features
4.  */
5. 
6. class ShoppingPage {
7.   constructor() {
8.     this.navToggle = document.querySelector('.nav-toggle');
9.     this.navList = document.querySelector('.nav-list');
10.     this.navLinks = document.querySelectorAll('.nav-list a');
11.     this.newsletterForm = document.querySelector('.newsletter-form');
12.     this.emailInput = document.querySelector('#email-input');
13.     this.errorMessage = document.querySelector('#email-error');
14.     this.newsletterNotice = document.querySelector('.newsletter-notice');
15.     
16.     this.init();
17.   }
18. 
19.   init() {
20.     this.setupNavigation();
21.     this.setupForm();
22.     this.setupCountdowns();
23.   }
24. 
25.   /**
26.    * Setup mobile navigation toggle
27.    */
28.   setupNavigation() {
29.     if (!this.navToggle) return;
30. 
31.     this.navToggle.addEventListener('click', () => {
32.       const isExpanded = this.navToggle.getAttribute('aria-expanded') === 'true';
33.       this.navToggle.setAttribute('aria-expanded', !isExpanded);
34.       this.navList.classList.toggle('active');
35. 
36.       if (!isExpanded) {
37.         this.navToggle.innerHTML = '<span></span><span></span><span></span>';
38.       }
39.     });
40. 
41.     // Close menu when a link is clicked
42.     this.navLinks.forEach(link => {
43.       link.addEventListener('click', () => {
44.         this.navToggle.setAttribute('aria-expanded', 'false');
45.         this.navList.classList.remove('active');
46.       });
47.     });
48. 
49.     // Close menu on Escape
