 /**
  * Shopping Home Page - Vanilla JavaScript
  * Handles navigation, forms, and interactive features
  */

 class ShoppingPage {
   constructor() {
     this.navToggle = document.querySelector('.nav-toggle');
     this.navList = document.querySelector('.nav-list');
     this.navLinks = document.querySelectorAll('.nav-list a');
     this.newsletterForm = document.querySelector('.newsletter-form');
     this.emailInput = document.querySelector('#email-input');
     this.errorMessage = document.querySelector('#email-error');
     this.newsletterNotice = document.querySelector('.newsletter-notice');

     this.init();
   }

   init() {
     this.setupNavigation();
     this.setupForm();
     this.setupCountdowns();
   }

   /**
    * Setup mobile navigation toggle
    */
   setupNavigation() {
     if (!this.navToggle) return;

     this.navToggle.addEventListener('click', () => {
       const isExpanded = this.navToggle.getAttribute('aria-expanded') === 'true';
       this.navToggle.setAttribute('aria-expanded', !isExpanded);
       this.navList.classList.toggle('active');

       if (!isExpanded) {
         this.navToggle.innerHTML = '<span></span><span></span><span></span>';
       }
     });

     // Close menu when a link is clicked
     this.navLinks.forEach(link => {
       link.addEventListener('click', () => {
         this.navToggle.setAttribute('aria-expanded', 'false');
         this.navList.classList.remove('active');
       });
     });

     // Close menu on Escape
     document.addEventListener('keydown', (e) => {
       if (e.key === 'Escape' && this.navList.classList.contains('active')) {
         this.navToggle.setAttribute('aria-expanded', 'false');
         this.navList.classList.remove('active');
         this.navToggle.focus();
       }
     });
   }

   /**
    * Setup newsletter form with validation
    */
   setupForm() {
     if (!this.newsletterForm) return;

     this.newsletterForm.addEventListener('submit', (e) => {
       e.preventDefault();

       if (this.validateEmail()) {
         this.submitNewsletter();
       }
     });

     this.emailInput.addEventListener('blur', () => {
       this.validateEmail();
     });

     this.emailInput.addEventListener('input', () => {
       if (this.errorMessage.classList.contains('show')) {
         this.errorMessage.classList.remove('show');
       }
